import datetime
import json
import logging
import os
from subprocess import CalledProcessError, check_output
from traceback import format_exception

from taf.ul.marvin.utilities import Utilities

try:
    from marvin_client import MarvinClient
    from marvin_client.exceptions import MarvinClientException
    marvin_client_available = True
except ImportError:
    MarvinClient = None
    MarvinClientException = None
    marvin_client_available = False

rat_templates = {
    'case_4G': ["case_common", "case_4G"],
    'case_5G': ["case_common", "case_5G"],
    'run_4G': ["run_common", "run_4G"],
    'run_5G': ["run_common", "run_5G"]
}


class MarvinUteClient:

    def __init__(self, marvin_side, marvin_folder, common_templates, organization, print_marvin_link,
                 create_test_cases, bts_id):
        self.utils = Utilities()
        self.rat_list = []
        self.marvin_side = marvin_side
        self.marvin_folder = marvin_folder
        self.common_templates = common_templates
        if not self.common_templates:
            self.common_templates = self.utils.set_default_common_templates_path()
        self.organization = organization
        self.print_marvin_link = print_marvin_link
        self.create_test_cases = create_test_cases
        self.test_cases = {}
        self.bts_id = str(bts_id)
        self.docker_side = "classic_prod" if "prod" in marvin_side else "classic_dev"
        self.data_collector_ae_host = "rsp-analysis-engine.ou.nsn-rdnet.net" if "prod" in marvin_side \
            else "dev-engine.analysis.dyn.nesc.nokia.net"
        self.data_collector_meta_host = "http://meta-service.marvin.ou.nsn-rdnet.net:9090" if "prod" in marvin_side \
            else "http://meta-service-dev.marvin.ou.nsn-rdnet.net:9090"
        self.marvin_link = "https://marvin.ou.nsn-rdnet.net/analyse?curId=" if "prod" in marvin_side \
            else "https://marvin-dev.ou.nsn-rdnet.net/analyse?curId="
        self.ovet_url = 'http://ovet.marvin.dyn.nesc.nokia.net:3002/api/v2/save' if "prod" in marvin_side \
            else 'http://ovet-dev.marvin.dyn.nesc.nokia.net:3002/api/v2/save'
        self.tc0_id = ""
        self.data_collector_test_run_id = ""
        self.data_collector_test_total_id = ""
        self.analysis_group_run_id = ""
        self.data_collector_timestamp = ""
        self.elastic_data_collectors = f"python {marvin_folder}/elastic_data_collectors.py"
        self.data_collector_output_file = f"{marvin_folder}/data_collector_identifiers.env"
        self.data_collector_test_case_id = ""
        self.analysis_group_case_id = ""
        self.data_collector_order = 0
        if marvin_client_available:
            self.marvin_client = MarvinClient(environment="prod" if marvin_side == "prod" else "dev")
            self.MarvinClientException = MarvinClientException
        else:
            self.marvin_client = None

    def import_marvin_client(self):
        try:
            if not marvin_client_available:
                from marvin_client import MarvinClient  # type: ignore[import]
                from marvin_client.exceptions import MarvinClientException  # type: ignore[import]
                self.MarvinClientException = MarvinClientException
                self.marvin_client = MarvinClient(environment="prod" if self.marvin_side == "prod" else "dev")
        except ImportError as e:
            logging.error(f"Error: {e} when trying to import MarvinClient\n"
                          f"{''.join(format_exception(type(e), e, e.__traceback__))}")
            raise ImportError("MarvinClient couldn't be installed. Please check logs.")

    def update_collectors(self, proxy=False, script_update=True, install_marvin_from_rsp_pypi=False):
        try:
            check_output("docker container ls -a | grep 'data_collector$'", shell=True).decode().strip()
            logging.debug("Docker container is already running")
        except CalledProcessError:
            if script_update:
                logging.debug("Updating collectors")
                # marvin-cli
                if install_marvin_from_rsp_pypi:
                    self.utils.check_output_with_retries("pip install --upgrade marvin-client "
                                                         "--index-url="
                                                         "https://artifactory-espoo2.int.net.nokia.com/artifactory/api/"
                                                         "pypi/pypi-rsp-ta-local/simple", no_std_messages=True)
                # Data collector
                proxy_option = " --no-proxy" if not proxy else ""
                self.utils.check_output_with_retries(
                    f"wget{proxy_option} -T 10 -t 1 -P {self.marvin_folder} "
                    r"https://rsp-ta-ci-file.es-si-s3-z2.eecloud.nsn-net.net/data-collector/"
                    r"datacollector_scripts.zip", env=True if proxy else None, no_std_messages=True)
                self.utils.check_output_with_retries(f"unzip -o {self.marvin_folder}/datacollector_scripts.zip "
                                                     f"-d {self.marvin_folder}  && "
                                                     f"rm {self.marvin_folder}/datacollector_scripts.zip",
                                                     no_std_messages=True)

                # AECLI
                self.utils.check_output_with_retries(f"wget{proxy_option} -T 10 -t 1 -P {self.marvin_folder} "
                                                     f"{self.data_collector_ae_host}/cli/aecli-linux-amd64.gz",
                                                     env=True if proxy else None, no_std_messages=True)
                self.utils.check_output_with_retries(f"gunzip -f {self.marvin_folder}/aecli-linux-amd64.gz",
                                                     no_std_messages=True)
                self.utils.check_output_with_retries(f"chmod +x {self.marvin_folder}/aecli-linux-amd64",
                                                     no_std_messages=True)
            if os.path.exists(f"{self.marvin_folder}/start_docker.sh"):
                logging.debug("Starting docker container for data collector")
                # Start docker
                self.utils.check_output_with_retries(f"{self.marvin_folder}/start_docker.sh "
                                                     f"--config-name={self.docker_side} "
                                                     "sudo=True", no_std_messages=True)

    def start_and_stop_init_test_steps(self):
        self.marvin_client.test_control.start_test_step(self.bts_id, self.data_collector_test_run_id,
                                                        self.tc0_id, "1")
        self.marvin_client.test_control.stop_test_step(self.bts_id, self.data_collector_test_run_id,
                                                       self.tc0_id, "1", verdict="Passed")
        self.marvin_client.test_control.start_test_step(self.bts_id, self.data_collector_test_run_id,
                                                        self.tc0_id, "2")
        self.marvin_client.test_control.stop_test_step(self.bts_id, self.data_collector_test_run_id,
                                                       self.tc0_id, "2", verdict="Passed")
        self.marvin_client.test_control.start_test_step(self.bts_id, self.data_collector_test_run_id,
                                                        self.tc0_id, "3")
        self.marvin_client.test_control.stop_test_step(self.bts_id, self.data_collector_test_run_id,
                                                       self.tc0_id, "3", verdict="Passed")
        self.marvin_client.test_control.start_test_step(self.bts_id, self.data_collector_test_run_id,
                                                        self.tc0_id, "4")
        self.marvin_client.test_control.stop_test_step(self.bts_id, self.data_collector_test_run_id,
                                                       self.tc0_id, "4", verdict="Passed")
        self.marvin_client.test_control.start_test_step(self.bts_id, self.data_collector_test_run_id,
                                                        self.tc0_id, "5")
        self.marvin_client.test_control.stop_test_step(self.bts_id, self.data_collector_test_run_id,
                                                       self.tc0_id, "5", verdict="Passed")

    def fetch_single_snapshot(self, test_case=False, periodical=False):
        logging.debug("Fetching single snapshot for data collector")
        if test_case:
            self.utils.check_output_with_retries(f"{self.marvin_folder}/snapshot_to_glusterfs.py "
                                                 f"--tags 'Test case end' --wait", timeout=300)
        elif periodical:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
            self.utils.check_output_with_retries(f"{self.marvin_folder}/snapshot_to_glusterfs.py --run-id "
                                                 f"{self.data_collector_test_run_id} --tags '{timestamp}'")
        else:
            self.utils.check_output_with_retries(f"{self.marvin_folder}/snapshot_to_glusterfs.py --run-id "
                                                 f"{self.data_collector_test_run_id} --tags 'Test run end' --wait",
                                                 timeout=300)

    def _find_newest_release_template(self, folder):
        release_dirs = []
        base_path = os.path.join(str(self.common_templates), "release", folder)
        if not os.path.exists(base_path):
            return ""
        for entry in os.listdir(base_path):
            entry_path = os.path.join(base_path, entry)
            if os.path.isdir(entry_path):
                release_dirs.append(entry_path)
        if not release_dirs:
            logging.debug(f"No release-specific templates found for {base_path}")
            return ""
        # Sort by release name (last part of the path), not full path
        release_dirs.sort(key=lambda p: os.path.basename(p), reverse=True)
        newest_release_path = release_dirs[0]
        logging.debug(f"Using newest release-specific template: {newest_release_path}")
        return newest_release_path

    def _add_paths(self, template_type, test_case_templates):
        # Handle custom templates for case_
        if test_case_templates and template_type == "case_":
            logging.debug(f"Adding template paths: {test_case_templates}")
            return ",".join(test_case_templates)
        # Collect all relevant template paths
        collected_paths = self._collect_paths(template_type, test_case_templates)
        logging.debug(f"Adding template paths: {list(collected_paths)}")
        return ",".join(collected_paths)

    def _collect_paths(self, template_type, test_case_templates):
        paths = set()
        # Add custom templates if provided
        if test_case_templates:
            paths.update(test_case_templates)
        # Add paths for each RAT
        for rat in self.rat_list:
            self._add_release_and_common_paths(paths, template_type, rat)
        return paths

    def _add_release_paths(self, paths, template_type, rat):
        # Add release path if available
        release = self.utils.get_sw_release_via_targetbd()
        if release:
            release_path = os.path.join(self.common_templates, "release", f"{template_type}{rat}", f"{release}")
            if os.path.exists(str(release_path)):
                paths.add(str(release_path))
            else:
                logging.debug("Release-specific template path not found, searching for newest available release")
                newest_release_path = self._find_newest_release_template(f"{template_type}{rat}")
                if newest_release_path:
                    paths.add(str(newest_release_path))

    def _convert_snapshot_files(self, path):
        file_listing = os.listdir(str(path))
        converted_file = ""
        converted_files = []
        for a_file in file_listing:
            file_without_extension = os.path.splitext(a_file)[0]
            is_converted = any(file_without_extension in converted_file for converted_file in converted_files)
            if "snapshot" in a_file and ".txt" in a_file and not is_converted:
                file_path = os.path.join(str(path), a_file)
                converted_file = os.path.join(str(path), f"{os.path.splitext(a_file)[0]}_converted.json")
                converted_files.append(converted_file)
                self.utils.check_output_with_retries(
                    f"{self.marvin_folder}/aecli-linux-amd64 helpers snapshot-transform -i {file_path} -o "
                    f"{converted_file}"
                )

    def _add_release_and_common_paths(self, paths, template_type, rat):
        self._add_release_paths(paths, template_type, rat)
        common_rat_path = os.path.join(self.common_templates, f"{template_type}common")
        if os.path.exists(str(common_rat_path)):
            paths.add(str(common_rat_path))
        common_path = os.path.join(self.common_templates, "common")
        if os.path.exists(str(common_path)):
            self._convert_snapshot_files(common_path)
            paths.add(str(common_path))
        rat_path = os.path.join(self.common_templates, f"{template_type}{rat}")
        if os.path.exists(str(rat_path)):
            paths.add(str(rat_path))

    def import_analysis(self, template_type, test_case_templates=None):
        paths_str = self._add_paths(template_type, test_case_templates)
        if self.data_collector_test_case_id:
            logging.debug("Creating pm-drops")
            self.utils.check_output_with_retries(
                f"{self.marvin_folder}/aecli-linux-amd64 analysis create-pm-drops --metahost"
                f" '{self.data_collector_meta_host}' --folder '{paths_str}' "
                f"--case-id '{self.data_collector_test_case_id}'")
        logging.debug(f"Importing analysis: {paths_str}")
        return self.utils.check_output_with_retries(f"{self.marvin_folder}/aecli-linux-amd64 --host "
                                                    f"{self.data_collector_ae_host} analysis import "
                                                    f"--include '{paths_str}' "
                                                    f"-n '{self.organization}' --plain", decode=True)

    def _create_test_line(self, test_line_type="", role=None):
        test_line = {
            "status": ["Production"],
            "organization": [self.organization],
            "test_type": [test_line_type],
        }
        if role:
            test_line["bts_role"] = role
        self.marvin_client.test_control.update_test_line(self.bts_id, test_line)

    def create_test_run(self, cluster=None, test_run_type="CRT", test_line_type="", test_env=None, bts_role=None):
        self.rat_list = self.utils.check_rat()
        try:
            # Templates to be used in the case. Might need some automation to identify RAT
            self.data_collector_test_run_id = self.utils.create_random_uuid()
            self.data_collector_test_total_id = self.utils.create_random_uuid()
            self._create_test_line(test_line_type=test_line_type, role=bts_role)
            self.tc0_id = self.utils.create_random_uuid()
            test_run = {
                "id": self.data_collector_test_run_id,
                "test_type": [test_run_type],
                "organization": [self.organization],
                "exec_status": "Not started",
                "bts": {
                    "id": self.bts_id
                },
                "test_cases": [
                    {
                        "id": self.tc0_id,
                        "name": "Environment_setup",
                        "exec_order": "0",
                        "test_steps": [
                            {"id": "1", "name": "Environment Preparation"},
                            {"id": "2", "name": "BTS SW update"},
                            {"id": "3", "name": "Traffic simulation"},
                            {"id": "4", "name": "Logs collect"},
                            {"id": "5", "name": "Process Logs"}
                        ]
                    }]
            }
            if cluster:
                try:
                    cluster_name, cluster_id = cluster
                except ValueError:
                    cluster_name = None
                    cluster_id = None
                    logging.debug("Cluster information not provided correctly; skipping cluster assignment")
                test_run["test_line_cluster"] = {
                    "name": cluster_name,
                    "run_id": cluster_id
                }
            if test_env:
                test_run["test_env"] = test_env
            self.marvin_client.test_control.create_test_run(self.bts_id, test_run)
            self.analysis_group_run_id = self.import_analysis("run_")
            self.data_collector_timestamp = self.utils.check_output_with_retries("date +'%Y-%m-%dT%H:%M:%S.%6NZ' -u",
                                                                                 decode=True)
            # Create test in Elastic
            self.utils.check_output_with_retries(f"{self.elastic_data_collectors} --create --host localhost "
                                                 f"--test-run-id {self.data_collector_test_run_id} --timestamp "
                                                 f"{self.data_collector_timestamp} "
                                                 f"--output-file {self.data_collector_output_file}")

            if self.print_marvin_link:
                logging.debug(f"Link to marvin run: {self.marvin_link}{self.data_collector_test_run_id}")
        except self.MarvinClientException as e:
            logging.error(f"Error: {e} when trying to start Marvin\n"
                          f"{''.join(format_exception(type(e), e, e.__traceback__))}")

    def start_test_run(self, ref):
        logging.debug("Starting test run")
        reference_run_id = f" --reference-run-id {ref}" if ref else ""
        cmd = (f"{self.marvin_folder}/aecli-linux-amd64 --host {self.data_collector_ae_host} analysis execute"
               f" --runtime -a {self.analysis_group_run_id}"
               " --started-from 'RSP_Jenkins'"
               f" --run-id {self.data_collector_test_run_id}"
               f" --bts-id {self.bts_id}{reference_run_id}")
        self.utils.check_output_with_retries(cmd)
        self.marvin_client.test_control.start_test_run(self.bts_id, self.data_collector_test_run_id)
        self.marvin_client.test_control.start_test_case(self.bts_id, self.data_collector_test_run_id, self.tc0_id)
        self.start_and_stop_init_test_steps()
        self.marvin_client.test_control.stop_test_case(self.bts_id, self.data_collector_test_run_id, self.tc0_id,
                                                       exec_verdict="Passed")

    def create_test_case(self, test_case_name, test_case_templates=None):
        try:
            logging.debug("Creating test case")
            self.data_collector_test_case_id = self.utils.create_random_uuid()
            self.data_collector_order += 1
            if self.create_test_cases:
                self.test_cases[test_case_name] = self.data_collector_test_case_id
            test_case = {
                "id": self.data_collector_test_case_id,
                "name": test_case_name,
                "exec_order": self.data_collector_order,
            }
            self.marvin_client.test_control.create_test_case(self.bts_id, self.data_collector_test_run_id,
                                                             test_case)
            self.analysis_group_case_id = self.import_analysis("case_", test_case_templates=test_case_templates)
        except self.MarvinClientException as e:
            logging.error(f"Error: {e} when creating test cases\n"
                          f"{''.join(format_exception(type(e), e, e.__traceback__))}")

    def start_test_case(self, test_case_name, ref=None, adapter_list=None):
        logging.debug("Starting test case")
        test_case_id = self.data_collector_test_case_id
        if self.create_test_cases and self.test_cases.get(test_case_name):
            test_case_id = self.test_cases[test_case_name]
        reference_case_id = f" --reference-case-id {ref}" if ref else ""
        cmd = (f"{self.marvin_folder}/aecli-linux-amd64 --host {self.data_collector_ae_host} analysis execute"
               f" --runtime -a {self.analysis_group_case_id}"
               " --started-from 'RSP_Jenkins'"
               f" --run-id {self.data_collector_test_run_id}"
               f" --case-id {test_case_id}"
               f" --test-phase-name '{test_case_name}'"
               f" --bts-id {self.bts_id}{reference_case_id}")
        self.utils.check_output_with_retries(cmd)
        adapter_str = self.utils.convert_adapters(adapter_list)
        meta = {"test_case": {"name": test_case_name}}
        meta_json = json.dumps(meta)
        cmd = (f"{self.elastic_data_collectors} --start --host localhost --test-run-id "
               f"{self.data_collector_test_run_id}  --meta '{meta_json}' --test-case-id "
               f"{test_case_id} --output-file {self.data_collector_output_file}"
               f"{adapter_str}")
        self.utils.check_output_with_retries(cmd)

        self.marvin_client.test_control.start_test_case(self.bts_id, self.data_collector_test_run_id,
                                                        test_case_id)
        self.utils.check_output_with_retries(f'echo "" >> {self.data_collector_output_file}')
        self.utils.check_output_with_retries('echo "DATA_COLLECTOR_TEST_TOTAL_ID='
                                             f'{self.data_collector_test_total_id}" >> '
                                             f'{self.data_collector_output_file}')

    def stop_test_case(self, verdict="Passed", test_case_name=""):
        logging.debug("Stopping test case")
        test_case_id = self.data_collector_test_case_id
        if self.create_test_cases and self.test_cases.get(test_case_name):
            test_case_id = self.test_cases[test_case_name]
        cmd = (f"{self.elastic_data_collectors} --stop --host localhost --test-run-id "
               f"{self.data_collector_test_run_id}  --test-case-id "
               f"{test_case_id}")
        self.utils.check_output_with_retries(cmd)
        verdict = self.utils.check_verdict(verdict)
        self.marvin_client.test_control.stop_test_case(self.bts_id, self.data_collector_test_run_id,
                                                       test_case_id, exec_verdict=verdict)

    def stop_test_run(self, verdict="Passed"):
        logging.debug("Stopping test run")
        cmd = (f"{self.elastic_data_collectors} --stop --host localhost --test-run-id "
               f"{self.data_collector_test_run_id}")
        self.utils.check_output_with_retries(cmd)
        verdict = self.utils.check_verdict(verdict)
        self.marvin_client.test_control.stop_test_run(self.bts_id, self.data_collector_test_run_id,
                                                      exec_verdict=verdict)

    def return_final_verdict(self, timeout=20):
        api_link = f"{self.data_collector_meta_host}/api/v1/test_runs/{self.data_collector_test_run_id}"
        logging.debug(f"Link to run in api: {api_link}")
        result = self.utils.retrieve_result_from_analysis_response(api_link, timeout)

        return result

    def return_test_case_verdict(self, test_case_name, timeout=20):
        test_case_id = self.data_collector_test_case_id
        if self.create_test_cases and self.test_cases.get(test_case_name):
            test_case_id = self.test_cases[test_case_name]
        api_link = f"{self.data_collector_meta_host}/api/v1/test_cases/{test_case_id}"
        logging.debug(f"Link to test case in api: {api_link}")
        result = self.utils.retrieve_result_from_analysis_response(api_link, timeout, test_case=True)

        return result

    def stop_docker(self, no_std_messages=False):
        try:
            if not no_std_messages:
                self.utils.check_output_with_retries("docker container ls -a | grep 'data_collector$'",
                                                     no_std_messages=no_std_messages,
                                                     suppress_errors=True)
            self.utils.check_output_with_retries(os.path.join(self.marvin_folder, "stop_docker.sh"),
                                                 no_std_messages=no_std_messages)
            if not no_std_messages:
                self.utils.check_output_with_retries("docker container ls -a | grep 'data_collector$'",
                                                     no_std_messages=no_std_messages,
                                                     suppress_errors=True)
        except CalledProcessError:
            logging.debug("Docker 'data_collector' container stopped")

    def add_marvin_link_to_rp(self, test_case_name=""):
        """
        Usable only on UTE cases via Cloud Manager

        :param test_case_name: Name of the test case to link to. If empty, links to the last created test case.
                               Usable only if create_test_cases is True.
        """
        try:
            from robot.libraries.BuiltIn import BuiltIn
            if test_case_name and self.create_test_cases and self.test_cases.get(test_case_name):
                self.data_collector_test_case_id = self.test_cases[test_case_name]
            BuiltIn().import_library("taf.sw.reporting_portal")
            BuiltIn().run_keyword(
                "taf.sw.reporting_portal.add_to_test_data",
                {"marvin_ta_uuid": self.data_collector_test_case_id})
        except ImportError:
            logging.debug("robot.libraries.BuiltIn not available; skipping adding marvin link to RP")

    def send_results_to_ovet(self, file_location, test_case_name=""):
        """
        :param str file_location: Location of the file to be sent to OVET.
        :param str test_case_name: Name of the test case to link to. If empty, links to the last created test case.
                               Usable only if create_test_cases is True.
        """
        try:
            if test_case_name and self.create_test_cases and self.test_cases.get(test_case_name):
                self.data_collector_test_case_id = self.test_cases[test_case_name]
            payload = {
                "client_info": {
                    "client": "kafka_messenger",
                    "page": "tti_trace",
                },
                "payload": {
                    "run_id": self.data_collector_test_run_id,
                    "case_id": self.data_collector_test_case_id,
                    "file_location": file_location
                },
            }
            data = self.utils.fetch_analysis_data(self.ovet_url, data=payload)
            if data:
                if data.get("error"):
                    logging.error(f"Error sending results to OVET for test case {self.data_collector_test_case_id}: "
                                f"{data['error']}")
                else:
                    logging.debug(f"Successfully sent results to OVET for test case {self.data_collector_test_case_id}")
            else:
                logging.error(f"Error sending results to OVET for test case {self.data_collector_test_case_id}: ")
        except Exception as e:
            logging.error(f"Error sending results to OVET for test case {self.data_collector_test_case_id}: "
                          f"{e.__class__.__name__} {e}\n"
                          f"{''.join(format_exception(type(e), e, e.__traceback__))}")
